{
  "status": "plan",
  "steps": [
    {
      "op": "derive",
      "input": "scores",
      "as": "step1",
      "column": "total",
      "expr": "(innovation if not is_null(innovation) else 0) + (execution if not is_null(execution) else 0) + (polish if not is_null(polish) else 0)"
    },
    {
      "op": "derive",
      "input": "step1",
      "as": "step2",
      "column": "cnt",
      "expr": "(1 if not is_null(innovation) else 0) + (1 if not is_null(execution) else 0) + (1 if not is_null(polish) else 0)"
    },
    {
      "op": "aggregate",
      "input": "step2",
      "as": "step3",
      "group_by": ["judge"],
      "metrics": [
        {
          "as": "sum_marks",
          "fn": "sum",
          "column": "total"
        },
        {
          "as": "total_cnt",
          "fn": "sum",
          "column": "cnt"
        }
      ]
    },
    {
      "op": "derive",
      "input": "step3",
      "as": "step4",
      "column": "avg_mark",
      "expr": "round(sum_marks / total_cnt, 1)"
    },
    {
      "op": "select",
      "input": "step4",
      "as": "output",
      "columns": ["judge", "avg_mark"]
    }
  ]
}

